package com.trainflow.pricing; import com.trainflow.program.ReturnRequest;import jakarta.validation.Valid;import java.util.UUID;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/training-cases/{caseId}/pricing")public class PricingController{private final PricingService s;public PricingController(PricingService s){this.s=s;}@GetMapping PricingResponse get(@PathVariable UUID caseId){return s.get(caseId);}@PostMapping@ResponseStatus(HttpStatus.CREATED)PricingResponse create(@PathVariable UUID caseId,@RequestBody(required=false)Object ignored){return s.create(caseId);}@PatchMapping PricingResponse update(@PathVariable UUID caseId,@Valid@RequestBody PricingRequest r){return s.update(caseId,r);}@PostMapping("/submit")PricingResponse submit(@PathVariable UUID caseId){return s.submit(caseId);}@PostMapping("/return")PricingResponse back(@PathVariable UUID caseId,@Valid@RequestBody ReturnRequest r){return s.back(caseId,r.reason());}@PostMapping("/validate")PricingResponse validate(@PathVariable UUID caseId){return s.validate(caseId);}}
